// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address addr1, address addr2) public {
        // Record the wards value for a random key before the call
        uint256 before1 = c.wards(address(this));
        uint256 before2 = c.wards(addr1);
        uint256 before3 = c.wards(addr2);

        // Call allowance on the public surface
        c.allowance(addr1, addr2);

        // Assert that none of these wards entries changed
        assertTrue(c.wards(address(this)) == before1 && c.wards(addr1) == before2 && c.wards(addr2) == before3);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address other) public {
        vm.assume(caller != address(0));
        // First, give caller authorization (so the caller is in wards mapping)
        c.rely(caller);

        // Record the caller's auth status before calling allowance
        uint256 before = c.wards(caller);

        // Call allowance (any arguments) - this should not change wards
        vm.prank(caller);
        c.allowance(other, other);

        // After allowance, the caller's auth status must be unchanged
        uint256 after = c.wards(caller);
        assertTrue(before == after, "allowance should not change wards");
    }
}

