pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address user, address addr, address spender) public {
        vm.assume(user != address(0) && addr != address(0) && spender != address(0));

        // Call rely to attempt to set the user's ward
        vm.prank(address(this)); // caller must be auth
        c.rely(user);

        // Record the totalSupply and balanceOf after rely
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 balanceOfAddr = c.balanceOf(addr);

        // Call allowance
        uint256 allowance = c.allowance(addr, spender);

        // The rule: after rely, allowance should equal totalSupply - balanceOf(addr)
        assertTrue(allowance == totalSupplyBefore - balanceOfAddr);
    }
}

