pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address from, address to, uint256 amount) public {
        // Ensure caller is not an authorized ward (ward[caller] == 0)
        vm.assume(caller != address(this)); // only the deployer is initially authorized

        // Record allowance before the call
        uint256 allowanceBefore = c.allowance(from, to);

        // Call transferFrom as the unauthorized caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, to, amount));

        // Record allowance after the call
        uint256 allowanceAfter = c.allowance(from, to);

        // The reference C: unauthorized callers cause the function to revert, so allowance should not change.
        // The buggy version: unauthorized callers might execute the function, changing allowance.
        // General rule: allowance is unchanged if the caller is not authorized.
        assertTrue(allowanceBefore == allowanceAfter, "allowance changed after unauthorized call");
    }
}

