pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(uint256 assets) public {
        // The reference C should return a non-zero value for at least some asset amounts
        // We test that the function exists and returns something; but the bug returns 0 always.
        // Since the reference might also return 0 for very small amounts, we use bound to ensure a meaningful range.
        uint256 bounded = bound(assets, 1000, 1e18);
        uint256 result = c.convertToShares(bounded);
        assertTrue(result != 0, "convertToShares should not be constant zero");
    }
}
